pub fn structural_binding_walk_selected_references(
    transport: Rc<OccurrenceTransport>,
    inputs: Rc<OccurrenceBindingCandidateInputs>,
    references: Rc<Vec<Rc<ReferenceOccurrence>>>,
) -> Rc<StructuralBindingWalk> {
    match (*occurrence_candidate_index_build(transport.clone(), inputs.clone())).clone() {
        OccurrenceCandidateIndexBuild::OccurrenceCandidateIndexTransportRefused {
            refusal: refusal,
            ..
        } => Rc::new(StructuralBindingWalk::StructuralBindingWalkRefused {
            refusal: Rc::new(
                StructuralBindingIndexRefusal::StructuralBindingTransportRefusal {
                    refusal: refusal.clone(),
                },
            ),
        }),
        OccurrenceCandidateIndexBuild::OccurrenceCandidateIndexModulePathRefused {
            refusal: refusal,
            ..
        } => Rc::new(StructuralBindingWalk::StructuralBindingWalkRefused {
            refusal: Rc::new(
                StructuralBindingIndexRefusal::StructuralBindingModulePathRefusal {
                    refusal: refusal.clone(),
                },
            ),
        }),
        OccurrenceCandidateIndexBuild::OccurrenceCandidateIndexExposureRefused {
            refusal: refusal,
            ..
        } => Rc::new(StructuralBindingWalk::StructuralBindingWalkRefused {
            refusal: Rc::new(
                StructuralBindingIndexRefusal::StructuralBindingExposureRefusal {
                    refusal: refusal.clone(),
                },
            ),
        }),
        OccurrenceCandidateIndexBuild::OccurrenceCandidateIndexAuthoredOrderRefused {
            refusal: refusal,
            ..
        } => Rc::new(StructuralBindingWalk::StructuralBindingWalkRefused {
            refusal: Rc::new(
                StructuralBindingIndexRefusal::StructuralBindingAuthoredOrderRefusal {
                    refusal: refusal.clone(),
                },
            ),
        }),
        OccurrenceCandidateIndexBuild::OccurrenceCandidateIndexDeclarationBucketRefused {
            occurrence: occurrence,
            ..
        } => Rc::new(StructuralBindingWalk::StructuralBindingWalkRefused {
            refusal: Rc::new(
                StructuralBindingIndexRefusal::StructuralBindingDeclarationBucketRefusal {
                    occurrence: occurrence.clone(),
                },
            ),
        }),
        OccurrenceCandidateIndexBuild::OccurrenceCandidateIndexReady { index: index, .. } => {
            Rc::new(StructuralBindingWalk::StructuralBindingWalkReady {
                population: bound_reference_population_from_projections(
                    resolve_all_references_via_structural_candidates(
                        transport.clone(),
                        index.clone(),
                        references.clone(),
                    ),
                ),
            })
        }
    }
}

pub fn structural_binding_walk(
    transport: Rc<OccurrenceTransport>,
    inputs: Rc<OccurrenceBindingCandidateInputs>,
) -> Rc<StructuralBindingWalk> {
    structural_binding_walk_selected_references(
        transport.clone(),
        inputs.clone(),
        transport.references.clone(),
    )
}

pub fn cross_file_binding_closure_assembly_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Collision-free cross-file assembly substrate (N3-B0): two independently parsed transports each mint raw OccurrenceId values from their own zero-based allocator, so a naive merge collides. occurrence_id_remap_state_with_fresh_map gives each transport its own old-ID => closure-ID remap keyed by the RAW id.value (never reused across transports); remap_occurrence_id/remap_containment_path/rekey_occurrence_transport/rekey_occurrence_binding_inputs rekey index, declarations, references, module paths, exposure rows, and authored-order rows TOGETHER against that one remap map, so every row for one transport lands on the SAME closure identity for the same raw id. assemble_cross_file_binding_closure rekeys the consumer with a fresh allocator and a fresh remap map, then folds providers each with a FRESH remap map but the ALLOCATOR CARRIED FORWARD from the prior step -- this is the mechanism that makes two transports that both minted raw id 0 land on distinct closure ids. module_path_file_index_from_rows validates the accumulated module=>file rows fail-closed (ModulePathFileDuplicateSame vs ModulePathFileConflict), never last-write-wins.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct OccurrenceIdRemapState {
    pub allocator: OccurrenceIdAllocator,
    pub remap: Rc<HashMap<i64, OccurrenceId>>,
}

pub fn occurrence_id_remap_state_with_fresh_map(
    allocator: OccurrenceIdAllocator,
) -> Rc<OccurrenceIdRemapState> {
    Rc::new(OccurrenceIdRemapState {
        allocator: allocator.clone(),
        remap: panic!("call target identity was not established before Rust emission")(),
    })
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct OccurrenceIdRemapResult {
    pub id: OccurrenceId,
    pub state: Rc<OccurrenceIdRemapState>,
}

pub fn remap_occurrence_id(
    id: OccurrenceId,
    state: Rc<OccurrenceIdRemapState>,
) -> Rc<OccurrenceIdRemapResult> {
    match v1_rt::map_get(&state.remap.clone(), id.value.clone()) {
        Some(remapped) => Rc::new(OccurrenceIdRemapResult {
            id: remapped.clone(),
            state: state.clone(),
        }),
        None => {
            let allocated =
                crate::std_occurrence_identity::alloc_occurrence_id(state.allocator.clone());
            Rc::new(OccurrenceIdRemapResult {
                id: allocated.id.clone(),
                state: Rc::new(OccurrenceIdRemapState {
                    allocator: allocated.alloc.clone(),
                    remap: v1_rt::rc_map_insert(
                        state.remap.clone(),
                        id.value.clone(),
                        allocated.id.clone(),
                    ),
                }),
            })
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct OccurrenceContainmentRemapResult {
    pub path: Rc<OccurrenceContainmentPath>,
    pub state: Rc<OccurrenceIdRemapState>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct OccurrenceAncestorRemapBuild {
    pub ancestors: Rc<Vec<OccurrenceId>>,
    pub state: Rc<OccurrenceIdRemapState>,
}

pub fn remap_containment_path(
    path: Rc<OccurrenceContainmentPath>,
    state: Rc<OccurrenceIdRemapState>,
) -> Rc<OccurrenceContainmentRemapResult> {
    {
        let ancestors_build = path.ancestors.clone().iter().cloned().fold(
            Rc::new(OccurrenceAncestorRemapBuild {
                ancestors: Rc::new(vec![]),
                state: state.clone(),
            }),
            |acc: Rc<OccurrenceAncestorRemapBuild>, ancestor: OccurrenceId| {
                let acc = v1_rt::take_owned(acc);
                {
                    let remapped = remap_occurrence_id(ancestor.clone(), acc.state);
                    Rc::new(OccurrenceAncestorRemapBuild {
                        ancestors: Rc::new({
                            let mut __cons_v = (*acc.ancestors).clone();
                            __cons_v.insert(0, remapped.id.clone());
                            __cons_v
                        }),
                        state: remapped.state.clone(),
                    })
                }
            },
        );
        let terminal_remapped =
            remap_occurrence_id(path.terminal.clone(), ancestors_build.state.clone());
        Rc::new(OccurrenceContainmentRemapResult {
            path: Rc::new(OccurrenceContainmentPath {
                ancestors: v1_rt::reverse(ancestors_build.ancestors.clone()),
                terminal: terminal_remapped.id.clone(),
            }),
            state: terminal_remapped.state.clone(),
        })
    }
}

